import { createContext, useContext, useState, useCallback } from "react";

const AppContext = createContext(null);

export function AppProvider({ children }) {
  const [user, setUser] = useState(null);
  const [hobbies, setHobbies] = useState([]);
  const [posts, setPosts] = useState([]);
  const [postsLoaded, setPostsLoaded] = useState(false);
  const [chatrooms, setChatrooms] = useState([]);
  const [chatroomsLoaded, setChatroomsLoaded] = useState(false);

  const login = useCallback((username) => setUser(username), []);
  const signup = useCallback((username) => setUser(username), []);
  const updateHobbies = useCallback((selected) => setHobbies(selected), []);

  const vote = useCallback((postId, direction) => {
    setPosts((prev) =>
      prev.map((p) => {
        if (p.id !== postId) return p;
        let upvotes = p.upvotes;
        let userVote = p.userVote;
        if (direction === "up") {
          if (userVote === "up") {
            upvotes -= 1;
            userVote = null;
          } else if (userVote === "down") {
            upvotes += 2;
            userVote = "up";
          } else {
            upvotes += 1;
            userVote = "up";
          }
        } else {
          if (userVote === "down") {
            upvotes += 1;
            userVote = null;
          } else if (userVote === "up") {
            upvotes -= 2;
            userVote = "down";
          } else {
            upvotes -= 1;
            userVote = "down";
          }
        }
        return { ...p, upvotes, userVote };
      }),
    );
  }, []);

  const addComment = useCallback((postId, text, author) => {
    setPosts((prev) =>
      prev.map((p) =>
        p.id !== postId
          ? p
          : {
              ...p,
              comments: [
                ...p.comments,
                {
                  id: `c${Date.now()}`,
                  author,
                  text,

                  upvotes: 0,
                },
              ],
            },
      ),
    );
  }, []);

  const addPost = useCallback((hobby, title, body, author) => {
    setPosts((prev) => [
      {
        id: `p${Date.now()}`,
        hobby,
        subreddit: hobby,
        author,

        title,
        body,
        upvotes: 1,
        userVote: "up",
        comments: [],
      },
      ...prev,
    ]);
  }, []);

  const sendChatMessage = useCallback((chatroomId, text, author) => {
    setChatrooms((prev) =>
      prev.map((c) =>
        c.id !== chatroomId
          ? c
          : {
              ...c,
              messages: [...c.messages, { id: `m${Date.now()}`, author, text }],
            },
      ),
    );
  }, []);

  const value = {
    user,
    hobbies,
    posts,
    postsLoaded,
    chatrooms,
    chatroomsLoaded,
    login,
    signup,
    updateHobbies,
    vote,
    addComment,
    addPost,
    sendChatMessage,
    setPosts,
    setPostsLoaded,
    setChatrooms,
    setChatroomsLoaded,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error("useApp must be used within AppProvider");
  return ctx;
}
